True from collections import Counter

def transform(grid):
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    marker = next(value for value, _ in counts.most_common() if value != background)
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == marker]
        for left, right in zip(positions, positions[1:]):
            for c in range(left + 1, right):
                if grid[r][c] == background:
                    out[r][c] = 3
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        for top, bottom in zip(positions, positions[1:]):
            for r in range(top + 1, bottom):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out
